const sql = `
CREATE TABLE IF NOT EXISTS device_log (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    ts          TEXT    NOT NULL,
    device_id   TEXT    NOT NULL,
    device_type TEXT,
    location    TEXT,
    payload     TEXT,
    event       TEXT
);
CREATE INDEX IF NOT EXISTS idx_log_ts        ON device_log(ts);
CREATE INDEX IF NOT EXISTS idx_log_device_ts ON device_log(device_id, ts);
CREATE INDEX IF NOT EXISTS idx_log_event     ON device_log(event);

CREATE TABLE IF NOT EXISTS device_config (
    device_id     TEXT PRIMARY KEY,
    device_type   TEXT,
    location      TEXT,
    friendly_name TEXT,
    enabled       INTEGER DEFAULT 1,
    extra         TEXT
);

CREATE TABLE IF NOT EXISTS schedule (
    id            INTEGER PRIMARY KEY AUTOINCREMENT,
    name          TEXT    NOT NULL,
    device_id     TEXT    NOT NULL,
    device_type   TEXT,
    action        TEXT    NOT NULL,
    action_params TEXT,
    sch_minute    TEXT    DEFAULT '*',
    sch_hour      TEXT    DEFAULT '*',
    sch_dow       TEXT    DEFAULT '*',
    sch_dom       TEXT    DEFAULT '*',
    sch_month     TEXT    DEFAULT '*',
    enabled       INTEGER DEFAULT 1,
    one_shot      INTEGER DEFAULT 0,
    last_run      TEXT,
    created_at    TEXT    DEFAULT (datetime('now')),
    updated_at    TEXT
);
CREATE INDEX IF NOT EXISTS idx_sch_enabled ON schedule(enabled);
CREATE INDEX IF NOT EXISTS idx_sch_device  ON schedule(device_id);
`;

msg.topic   = sql;
msg.payload = [];
return msg;

const sql = `
INSERT OR IGNORE INTO device_config VALUES
('0x384C', 'mcb', 'zone_A', 'MCB Tong zone A', 1, '{"gateway":"tasmota_6DCAA8","power_attr":"0110","attrs":{"0110":{"key":"power","type":"bool"},"0272":{"key":"meas_0272","type":"number"},"0273":{"key":"meas_0273","type":"number"},"0274":{"key":"meas_0274","type":"number"},"0276":{"key":"meas_0276","type":"number"},"0277":{"key":"meas_0277","type":"number"},"0283":{"key":"meas_0283","type":"number"},"0466":{"key":"meas_0466","type":"number"},"0467":{"key":"meas_0467","type":"number"},"0468":{"key":"meas_0468","type":"number"},"0469":{"key":"meas_0469","type":"number"},"046B":{"key":"meas_046B","type":"number"},"046E":{"key":"meas_046E","type":"number"},"0170":{"key":"meas_0170","type":"number"},"0201":{"key":"state_0201","type":"number"},"027D":{"key":"state_027D","type":"number"},"0006":{"key":"raw_hex","type":"hex"}}}'),
('0x8150', 'ac_controller', 'zone_B', 'Dieu hoa zone B', 1, '{"gateway":"tasmota_6DCAA8","power_attr":"0101","ac_power_attr":"0101","ac_temp_attr":"0202","ac_mode_attr":"0405","ac_mode_map":{"off":0,"cool":1,"heat":2,"fan_only":3,"dry":4},"attrs":{"0101":{"key":"power","type":"bool"},"0202":{"key":"temperature","type":"number"},"0405":{"key":"mode","type":"number"}}}');
`;
msg.topic   = sql;
msg.payload = [];
return msg;

const configs = {};
const rows = msg.payload || [];
rows.forEach(row => {
    const extra = row.extra ? JSON.parse(row.extra) : {};
    configs[row.device_id] = {
        type:          row.device_type,
        location:      row.location,
        friendly_name: row.friendly_name,
        enabled:       row.enabled,
        gateway:       extra.gateway || '',
        extra:         extra,
    };
});
global.set('device_configs', configs);
node.status({ fill: 'green', shape: 'dot', text: `${Object.keys(configs).length} devices loaded` });
node.warn(`[Startup] Loaded ${Object.keys(configs).length} device configs`);
return null;

const rows = msg.payload || [];
global.set('schedules', rows);
node.status({ fill: 'green', shape: 'dot', text: `${rows.length} schedules loaded` });
node.warn(`[Startup] Loaded ${rows.length} schedules`);
return null;

// ── L1: Parse tele/+/SENSOR voi ZbReceived ──────────────────
const topic = msg.topic;
const parts = topic.split('/');
const configs = global.get('device_configs') || {};

// ── Khi chua co config, return null ─────────────────────────
if (Object.keys(configs).length === 0) {
    node.status({ fill: 'red', shape: 'dot', text: 'no configs' });
    return null;
}

// ── Case 1: tele/+/SENSOR → extract ZbReceived ──────────────
if (topic.startsWith('tele/') && parts[2] === 'SENSOR') {
    const gateway = parts[1];
    const zb = msg.payload && msg.payload.ZbReceived;
    if (!zb) return null;

    const msgs = [];
    for (const [addr, data] of Object.entries(zb)) {
        if (!data || typeof data !== 'object') continue;
        const cfg = configs[addr];
        if (!cfg || !cfg.enabled) continue;

        msgs.push({
            topic:        topic,
            device_id:    addr,
            gateway:      gateway,
            device_type:  cfg.type || 'unknown',
            source:       'tasmota_zigbee',
            payload_raw:  data,
            link_quality: data.LinkQuality || null,
            endpoint:     data.Endpoint || null,
        });
    }

    if (msgs.length === 0) return null;
    node.status({ fill: 'green', shape: 'dot', text: `${msgs.length} dev` });
    return [msgs];
}

// ── Case 2: tele/+/LWT → de LWT handler xu ly rieng ────────
if (topic.startsWith('tele/') && parts[2] === 'LWT') {
    // Pass through to LWT handler (mqtt-in-lwt se bat rieng)
    // Main wildcard van bat nhung bo qua o day
    return null;
}

// ── Khac: log unknown ───────────────────────────────────────
return null;

// ── L1: LWT handler — cap nhat online state cho tat ca device cua gateway ──
const parts    = msg.topic.split('/');
const gatewayId = parts[1];
const isOnline  = (msg.payload === 'Online');

const configs = global.get('device_configs') || {};
const devices = global.get('devices') || {};
let updated = 0;

for (const [addr, cfg] of Object.entries(configs)) {
    if (cfg.extra && cfg.extra.gateway === gatewayId) {
        if (!devices[addr]) devices[addr] = {};
        devices[addr].online  = isOnline;
        devices[addr].lwt_ts  = new Date().toISOString();
        updated++;
    }
}
global.set('devices', devices);

const gateways = global.get('gateways') || {};
gateways[gatewayId] = { online: isOnline, last_seen: new Date().toISOString() };
global.set('gateways', gateways);

node.status({ fill: isOnline ? 'green' : 'red', shape: 'dot', text: `${gatewayId}: ${isOnline ? 'ON' : 'OFF'} (${updated}d)` });

msg._lwt_gateway   = gatewayId;
msg._lwt_online    = isOnline;
msg._lwt_dev_count = updated;
return msg;

// ── L2: GENERIC normalize — doc tu device_config.extra.attrs ─
// Tuong thich moi device type, chi can cau hinh trong extra

const raw  = msg.payload_raw || {};
const cfg  = (global.get('device_configs') || {})[msg.device_id] || {};
const extra = cfg.extra || {};
const attrs_cfg = extra.attrs || {};

const state = {
    online:       true,
    link_quality: msg.link_quality,
};

// ── Anh xa EF00/XXXX -> state property theo attrs_cfg ──────
for (const [key, val] of Object.entries(raw)) {
    if (!key.startsWith('EF00/')) continue;
    const attrId = key.slice(5);
    const mapping = attrs_cfg[attrId];

    if (mapping) {
        let v = val;
        switch (mapping.type) {
            case 'bool':
                v = (val === 1 || val === '1' || val === true);
                break;
            case 'number':
                v = Number(val);
                if (mapping.scale) v = v * mapping.scale;
                break;
            case 'hex':
                v = String(val);
                break;
            case 'string':
                v = String(val);
                break;
            default:
                v = val;
        }
        state[mapping.key] = v;
    } else {
        // Attr chua duoc mapping -> luu raw
        state[`raw_${attrId}`] = val;
    }
}

msg.device = {
    id:       msg.device_id,
    type:     cfg.type || 'unknown',
    location: cfg.location  || '',
    gateway:  msg.gateway   || extra.gateway || '',
    ts:       new Date().toISOString(),
    state:    state,
    raw:      raw,
};

return msg;

// ── L2→L3: Update global devices cache ──────────────────────
const d       = msg.device;
const devices = global.get('devices') || {};

const prev    = devices[d.id];
const changed = !prev
    || JSON.stringify(prev.state) !== JSON.stringify(d.state);

devices[d.id] = d;
global.set('devices', devices);

msg._state_changed = changed;
msg._prev_state    = prev ? prev.state : null;
return msg;

if (!msg._state_changed) { node.status({ fill: 'grey', shape: 'dot', text: 'no change' }); return null; }
function esc(v) { if (v === null || v === undefined) return 'NULL'; if (typeof v === 'number') return String(v); return "'" + String(v).replace(/'/g, "''") + "'"; }
const d = msg.device;
const vals = [d.ts, d.id, d.type, d.location, JSON.stringify(d.state), msg.event_type ?? 'state_change'];
msg.topic = 'INSERT INTO device_log (ts, device_id, device_type, location, payload, event) VALUES (' + vals.map(esc).join(',') + ')';
node.status({ fill: 'green', shape: 'dot', text: `log: ${d.id}` });
return msg;

function esc(v) { if (v === null || v === undefined) return 'NULL'; if (typeof v === 'number') return String(v); return "'" + String(v).replace(/'/g, "''") + "'"; }
const gateway = msg._lwt_gateway;
const isOnline = msg._lwt_online;
const devCount = msg._lwt_dev_count || 0;
const vals = [new Date().toISOString(), gateway, 'gateway', '', JSON.stringify({ online: isOnline, devices_affected: devCount }), isOnline ? 'gateway_online' : 'gateway_offline'];
msg.topic = 'INSERT INTO device_log (ts, device_id, device_type, location, payload, event) VALUES (' + vals.map(esc).join(',') + ')';
node.status({ fill: isOnline ? 'green' : 'red', shape: 'dot', text: gateway + ': ' + (isOnline ? 'ONLINE' : 'OFFLINE') });
return msg;

const now       = new Date();
const schedules = global.get('schedules') ?? [];

function fieldMatch(expr, val) {
    if (!expr || expr === '*') return true;
    if (expr.startsWith('*/')) return val % Number(expr.slice(2)) === 0;
    if (expr.includes('-')) { const [lo, hi] = expr.split('-').map(Number); return val >= lo && val <= hi; }
    if (expr.includes(',')) return expr.split(',').map(Number).includes(val);
    return Number(expr) === val;
}
function cronMatches(s, d) {
    return fieldMatch(s.sch_minute, d.getMinutes()) && fieldMatch(s.sch_hour, d.getHours()) && fieldMatch(s.sch_dow, d.getDay()) && fieldMatch(s.sch_dom, d.getDate()) && fieldMatch(s.sch_month, d.getMonth() + 1);
}

const triggered = schedules.filter(s => s.enabled && cronMatches(s, now));
if (triggered.length === 0) { node.status({ fill: 'grey', shape: 'dot', text: 'no trigger' }); return null; }

node.status({ fill: 'yellow', shape: 'dot', text: `${triggered.length} trig` });
msg.payload = triggered.map(s => ({ schedule_id: s.id, schedule_name: s.name, device_id: s.device_id, device_type: s.device_type, action: s.action, action_params: s.action_params ? JSON.parse(s.action_params) : {}, one_shot: s.one_shot, triggered_at: now.toISOString() }));
return msg;

// ── L4: DATA-DRIVEN command builder ───────────────────────────
// Doc device_config.extra de biet cach build ZbSend payload
// Mo rong: them action moi = them vao extra.custom_actions

const s = msg.payload;
const configs = global.get('device_configs') || {};
const cfg = configs[s.device_id] || {};
const extra = cfg.extra || {};
const gateway = cfg.gateway || extra.gateway;

if (!gateway) {
    node.warn(`No gateway for device ${s.device_id}`);
    return null;
}

// ── Resolve command writes tu extra ─────────────────────────
const writes = _buildWrites(s, extra);
if (!writes) {
    node.warn(`Cannot build cmd for action=${s.action} device=${s.device_id}`);
    return null;
}

msg.topic   = `cmnd/${gateway}/ZbSend`;
msg.payload = JSON.stringify({
    device: s.device_id,
    send: { Cluster: '0xEF00', Write: writes }
});

msg._schedule_id   = s.schedule_id;
msg._schedule_name = s.schedule_name;
msg._one_shot      = s.one_shot;
msg._log = { device_id: s.device_id, event: 'schedule_command', detail: `${s.schedule_name} -> ${s.action}` };
msg._cmd_device_id  = s.device_id;
msg._cmd_action     = s.action;

return msg;

// ── Helper: build Write object tu action + extra config ─────
function _buildWrites(s, extra) {
    const params = s.action_params || {};

    // 1. Kiem tra custom_actions truoc (mo rong tuy y)
    const custom = extra.custom_actions || {};
    if (custom[s.action]) {
        // Substitute {{var}} trong values
        const tmpl = JSON.stringify(custom[s.action]);
        const resolved = JSON.parse(tmpl.replace(/\{\{(\w+)\}\}/g, (_, k) => params[k] ?? ''));
        return resolved;
    }

    // 2. Built-in actions
    switch (s.action) {
        case 'POWER_ON':
            return { [extra.power_attr || '0110']: 1 };

        case 'POWER_OFF':
            return { [extra.power_attr || '0110']: 0 };

        case 'AC_SET': {
            const w = {};
            w[extra.ac_power_attr || '0101'] = 1;
            w[extra.ac_temp_attr  || '0202'] = params.temp || 25;
            const modeMap = extra.ac_mode_map || { off: 0, cool: 1, heat: 2, fan_only: 3, dry: 4 };
            w[extra.ac_mode_attr  || '0405'] = modeMap[params.mode] !== undefined ? modeMap[params.mode] : 1;
            return w;
        }

        case 'AC_OFF':
            return { [extra.ac_power_attr || '0101']: 0 };

        default:
            return null;
    }
}

function esc(v) { if (v === null || v === undefined) return 'NULL'; if (typeof v === 'number') return String(v); return "'" + String(v).replace(/'/g, "''") + "'"; }
const now = new Date().toISOString();
const id = msg._schedule_id;
if (msg._one_shot) {
    msg.topic = "UPDATE schedule SET enabled=0, last_run=" + esc(now) + ", updated_at=" + esc(now) + " WHERE id=" + esc(id);
} else {
    msg.topic = "UPDATE schedule SET last_run=" + esc(now) + ", updated_at=" + esc(now) + " WHERE id=" + esc(id);
}
const updated = (global.get('schedules') ?? []).map(s => s.id === id ? { ...s, last_run: now, enabled: msg._one_shot ? 0 : s.enabled } : s);
global.set('schedules', updated);
return msg;

function esc(v) { if (v === null || v === undefined) return 'NULL'; if (typeof v === 'number') return String(v); return "'" + String(v).replace(/'/g, "''") + "'"; }
if (!msg._log) return null;
const log = msg._log;
const now = new Date().toISOString();
const vals = [now, log.device_id, 'unknown', '', JSON.stringify({ command: log.detail, action: msg._cmd_action }), log.event];
msg.topic = 'INSERT INTO device_log (ts, device_id, device_type, location, payload, event) VALUES (' + vals.map(esc).join(',') + ')';
return msg;

const devices = global.get('devices') ?? {};
const configs = global.get('device_configs') ?? {};
msg.payload = Object.values(devices).map(d => ({
    'ID':        d.id,
    'Ten':       configs[d.id]?.friendly_name ?? d.id,
    'Loai':      d.type,
    'Gateway':   d.gateway || '—',
    'Trang thai': d.state?.power !== undefined ? (d.state.power ? 'ON' : 'OFF') : (d.state?.temperature !== undefined ? `${d.state.temperature}°C` : '—'),
    'Online':    d.state?.online ? '✓' : '✗',
    'LinkQ':     d.state?.link_quality ?? '—',
    'Cap nhat':  d.ts ? d.ts.slice(11, 19) : '—',
}));
return msg;

const deviceId = flow.get('manual_device_id');
if (!deviceId) { node.warn('No device selected'); return null; }

const configs = global.get('device_configs') || {};
const cfg = configs[deviceId];
if (!cfg || !cfg.extra) { node.warn('No config for ' + deviceId); return null; }

const extra = cfg.extra;
const gateway = cfg.gateway || extra.gateway;
const powerAttr = extra.power_attr || '0110';
const val = msg.payload === 'ON' ? 1 : 0;

msg.topic   = 'cmnd/' + gateway + '/ZbSend';
msg.payload = JSON.stringify({ device: deviceId, send: { Cluster: '0xEF00', Write: { [powerAttr]: val } } });
msg._manual_device_id = deviceId;
return msg;

function esc(v) { if (v === null || v === undefined) return 'NULL'; if (typeof v === 'number') return String(v); return "'" + String(v).replace(/'/g, "''") + "'"; }
const now = new Date().toISOString();
const did = msg._manual_device_id || 'unknown';
const vals = [now, did, 'unknown', '', JSON.stringify({ manual: msg.payload }), 'manual_command'];
msg.topic = 'INSERT INTO device_log (ts, device_id, device_type, location, payload, event) VALUES (' + vals.map(esc).join(',') + ')';
return msg;

function esc(v) { if (v === null || v === undefined) return 'NULL'; if (typeof v === 'number') return String(v); return "'" + String(v).replace(/'/g, "''") + "'"; }
const devId = (typeof msg.payload === 'string' && msg.payload !== 'refresh') ? msg.payload : 'all';
const filter = devId === 'all' ? '%' : devId;
msg.topic = 'SELECT ts, device_id, event, payload FROM device_log WHERE device_id LIKE ' + esc(filter) + ' ORDER BY ts DESC LIMIT 100';
return msg;

const form = flow.get('sched_form') || {};
const topic = msg.topic || '';

// Xac dinh field nao dang duoc gui (dung _msgid or widget index)
// Dung msg.payload de nhan biet kieu: string -> name/device_id/params/dow, number -> hour/minute
const label = (msg.ui || {}).label || '';
if (label.includes('Ten lich')) form.name = msg.payload;
else if (label.includes('Device ID')) form.device_id = msg.payload;
else if (label.includes('Hanh dong')) form.action = msg.payload;
else if (label.includes('Action params')) form.action_params = msg.payload;
else if (label.includes('Gio')) form.hour = msg.payload;
else if (label.includes('Phut')) form.minute = msg.payload;
else if (label.includes('Ngay')) form.dow = msg.payload;
else if (label.includes('Chay 1 lan')) form.one_shot = msg.payload;
else if (label.includes('Kich hoat')) form.enabled = msg.payload;

flow.set('sched_form', form);
return null;

function esc(v) { if (v === null || v === undefined) return 'NULL'; if (typeof v === 'number') return String(v); return "'" + String(v).replace(/'/g, "''") + "'"; }
const f = flow.get('sched_form') || {};
const now = new Date().toISOString();
if (!f.name || !f.device_id || !f.action) { node.warn('Missing fields: name, device_id, action'); return null; }
const min = String(f.minute ?? '*');
const hour = String(f.hour ?? '*');
const dow = f.dow || '*';
const params = f.action_params || null;
const vals = [f.name, f.device_id, f.action, params ? String(params) : 'NULL', min, hour, dow, f.enabled === '1' ? '1' : '0', f.one_shot === '1' ? '1' : '0', now];
msg.topic = 'INSERT INTO schedule (name, device_id, action, action_params, sch_minute, sch_hour, sch_dow, enabled, one_shot, created_at) VALUES (' + vals.map(esc).join(',') + ')';
return [msg, msg];

global.set('schedules', msg.payload || []);
node.status({ fill: 'green', shape: 'dot', text: (msg.payload||[]).length + ' sched' });
return null;

const form = flow.get('dev_config') || {};
const label = (msg.ui || {}).label || '';
if (label.includes('Device ID')) form.device_id = msg.payload;
else if (label.includes('Device Type')) form.device_type = msg.payload;
else if (label.includes('Gateway')) form.gateway = msg.payload;
else if (label.includes('Location')) form.location = msg.payload;
else if (label.includes('Friendly')) form.friendly_name = msg.payload;
else if (label.includes('Power attr')) form.power_attr = msg.payload;
else if (label.includes('Attrs mapping')) form.attrs_json = msg.payload;
else if (label.includes('Custom actions')) form.custom_actions_json = msg.payload;
flow.set('dev_config', form);
return null;

function esc(v) { if (v === null || v === undefined) return 'NULL'; if (typeof v === 'number') return String(v); return "'" + String(v).replace(/'/g, "''") + "'"; }
const f = flow.get('dev_config') || {};
if (!f.device_id || !f.device_type) { node.warn('Missing device_id or device_type'); return null; }
const extra = {};
if (f.gateway) extra.gateway = f.gateway;
if (f.power_attr) extra.power_attr = f.power_attr;
if (f.attrs_json) { try { extra.attrs = JSON.parse(f.attrs_json); } catch(e) {} }
if (f.custom_actions_json) { try { extra.custom_actions = JSON.parse(f.custom_actions_json); } catch(e) {} }
const vals = [f.device_id, f.device_type, f.location || '', f.friendly_name || '', '1', JSON.stringify(extra)];
msg.topic = 'INSERT OR REPLACE INTO device_config (device_id, device_type, location, friendly_name, enabled, extra) VALUES (' + vals.map(esc).join(',') + ')';
msg._reload_needed = true;
return msg;

const reload = flow.get('_force_reload') || msg._reload_needed;
if (!reload && !msg._reload_needed) return null;
msg.topic = 'SELECT * FROM device_config WHERE enabled = 1';
return msg;

const rows = msg.payload || [];
const configs = {};
rows.forEach(row => {
    const extra = row.extra ? JSON.parse(row.extra) : {};
    configs[row.device_id] = { type: row.device_type, location: row.location, friendly_name: row.friendly_name, enabled: row.enabled, gateway: extra.gateway || '', extra: extra };
});
global.set('device_configs', configs);
node.warn('[Reload] ' + Object.keys(configs).length + ' device configs loaded');
return null;

flow.set('_force_reload', true);
msg._reload_needed = true;
return msg;

const ctx = flow.get('ac_control') || {};
if (typeof msg.payload === 'number') ctx.temp = msg.payload;
if (typeof msg.payload === 'string' && msg.payload !== 'all') ctx.mode = msg.payload;
flow.set('ac_control', ctx);
return null;

const configs = global.get('device_configs') || {};
const acEntry = Object.entries(configs).find(function(e) { return e[1].type === 'ac_controller'; });
if (!acEntry) { node.warn('No ac_controller in config'); return null; }

const acId  = acEntry[0];
const extra = acEntry[1].extra || {};
const gateway = acEntry[1].gateway || extra.gateway;
const ctx = flow.get('ac_control') || {};

const writes = {};
writes[extra.ac_power_attr || '0101'] = 1;
writes[extra.ac_temp_attr  || '0202'] = ctx.temp || 24;
const modeMap = extra.ac_mode_map || { off: 0, cool: 1, heat: 2, fan_only: 3, dry: 4 };
writes[extra.ac_mode_attr  || '0405'] = modeMap[ctx.mode] !== undefined ? modeMap[ctx.mode] : 1;

msg.topic   = 'cmnd/' + gateway + '/ZbSend';
msg.payload = JSON.stringify({ device: acId, send: { Cluster: '0xEF00', Write: writes } });
return msg;

const configs = global.get('device_configs') || {};
const acEntry = Object.entries(configs).find(function(e) { return e[1].type === 'ac_controller'; });
if (!acEntry) { node.warn('No ac_controller'); return null; }

const acId  = acEntry[0];
const extra = acEntry[1].extra || {};
const gateway = acEntry[1].gateway || extra.gateway;
const offAttr = extra.ac_power_attr || extra.power_attr || '0101';

msg.topic   = 'cmnd/' + gateway + '/ZbSend';
msg.payload = JSON.stringify({ device: acId, send: { Cluster: '0xEF00', Write: { [offAttr]: 0 } } });
return msg;

const configs = global.get('device_configs') || {};
const opts = Object.entries(configs).map(function(e) {
    return { label: (e[1].friendly_name || e[0]) + ' (' + e[1].type + ')', value: e[0] };
});
msg.options = opts;
return msg;

const devices = global.get('devices') ?? {};
const allDevices = Object.values(devices);
const online     = allDevices.filter(d => d.state?.online).length;

const ac = allDevices.find(d => d.type === 'ac_controller');
const mcb = allDevices.find(d => d.type === 'mcb');

const alerts = [];
allDevices.forEach(d => {
    if (!d.state?.online) alerts.push(`${d.id}: OFFLINE`);
});

msg.topic   = 'hmi/status';
